/**
 * BioWordle v0.2 ("Restraint") — Interactive Cheminformatics & Peptide Motif Deduction Suite
 * ==========================================================================================
 * Consumes pre-compiled RDKit 2D SVGs, Chiral Morgan (ECFP4-like) Tanimoto matrices,
 * Henderson-Hasselbalch peptide properties, and the shared `feedback_spec` from
 * `window.BIOWORDLE_DATA` (generated by `build_puzzles.py`).
 */

(function (globalScope) {
  "use strict";

  // ---------------------------------------------------------------------------
  // 1. Pure Shared Feedback & State Engine (Exported for Node.js Golden Tests)
  // ---------------------------------------------------------------------------
  function fnv1aHash(str) {
    let h = 2166136261 >>> 0;
    for (let i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
  }

  function getUtcDateString(dateObj) {
    if (
      !dateObj &&
      typeof globalScope.__BIOWORDLE_TEST_UTC_DATE__ === "string" &&
      globalScope.__BIOWORDLE_TEST_UTC_DATE__.trim()
    ) {
      return globalScope.__BIOWORDLE_TEST_UTC_DATE__.trim();
    }
    const d = dateObj || new Date();
    const yyyy = d.getUTCFullYear();
    const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
    const dd = String(d.getUTCDate()).padStart(2, "0");
    return `${yyyy}-${mm}-${dd}`;
  }

  function getPreviousUtcDateString(utcDateStr) {
    const parts = utcDateStr.split("-").map(Number);
    const dt = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2] - 1));
    return getUtcDateString(dt);
  }

  function selectDailyIndex(game, profile, utcDate, scheduleHash, poolLength, customSeed) {
    if (!poolLength || poolLength <= 0) return 0;
    const seedStr = customSeed
      ? `${game}:${profile}:seed:${customSeed}:${scheduleHash}`
      : `${game}:${profile}:${utcDate}:${scheduleHash}`;
    return fnv1aHash(seedStr) % poolLength;
  }

  function evaluateDeltaFromSpec(guessVal, targetVal, fieldSpec) {
    const gVal = Number(guessVal);
    const tVal = Number(targetVal);
    const diff = Math.abs(gVal - tVal);
    const exactTol = Number(fieldSpec.exact_tol);
    const closeTol = Number(fieldSpec.close_tol);
    const closeDir = Boolean(fieldSpec.close_directional);
    const farDir = fieldSpec.far_directional !== undefined ? Boolean(fieldSpec.far_directional) : true;

    if (diff <= exactTol + 1e-9) {
      return { code: "E", cls: "match-exact", arrow: "✓" };
    }

    const direction = tVal > gVal ? "U" : "D";
    const dirArrow = direction === "U" ? "↑" : "↓";

    if (diff <= closeTol + 1e-9) {
      if (closeDir) {
        return { code: `C${direction}`, cls: "match-close", arrow: dirArrow };
      }
      return { code: "C", cls: "match-close", arrow: "≈" };
    }

    if (farDir) {
      return { code: `F${direction}`, cls: "match-far", arrow: dirArrow };
    }
    return { code: "F", cls: "match-far", arrow: "≠" };
  }

  function evaluateChemleFeedbackFromSpec(guess, target, simPct, profileSpec) {
    const isWin = guess.inchikey === target.inchikey || guess.id === target.id;
    const tSpec = profileSpec.tanimoto_bucket;
    const edges = tSpec.edges;
    const codes = tSpec.codes || ["LO", "MD", "HI"];
    const labels = tSpec.labels || ["Low", "Moderate", "High"];

    let simCode;
    let simLabel;
    let simBadgeCls;
    if (isWin || simPct === 100) {
      simCode = "WIN";
      simLabel = "Exact (100%)";
      simBadgeCls = "badge-emerald";
    } else if (simPct >= edges[1]) {
      simCode = codes[2];
      simLabel = labels[2];
      simBadgeCls = "badge-emerald";
    } else if (simPct >= edges[0]) {
      simCode = codes[1];
      simLabel = labels[1];
      simBadgeCls = "badge-amber";
    } else {
      simCode = codes[0];
      simLabel = labels[0];
      simBadgeCls = "badge-indigo";
    }

    const sigParts = [];
    if (isWin) {
      sigParts.push("WIN");
    } else {
      if (profileSpec.show_category_match_live) {
        sigParts.push(guess.Category === target.Category ? "CAT_EQ" : "CAT_NE");
      }
      if (tSpec.shown !== false) {
        sigParts.push(simCode);
      }
    }

    const cells = [];
    for (let i = 0; i < profileSpec.chemle_fields.length; i++) {
      const fSpec = profileSpec.chemle_fields[i];
      if (fSpec.shown === false) continue;
      const col = fSpec.name;
      const res = evaluateDeltaFromSpec(guess[col], target[col], fSpec);
      if (!isWin) {
        sigParts.push(res.code);
      }
      cells.push({
        name: col,
        label: fSpec.label,
        decimals: fSpec.decimals !== undefined ? fSpec.decimals : 1,
        value: guess[col],
        ...res,
      });
    }

    if (!isWin) {
      if (profileSpec.show_exact_tanimoto) {
        sigParts.push("SIM_PCT:" + Math.trunc(simPct));
      }
      if (profileSpec.show_functional_groups_live) {
        const gFg = new Set(guess.functional_groups || []);
        const tFg = target.functional_groups || [];
        const shared = [];
        for (let i = 0; i < tFg.length; i++) {
          if (gFg.has(tFg[i])) shared.push(tFg[i]);
        }
        shared.sort();
        sigParts.push("FG:" + shared.join(","));
      }
    }

    return {
      signature: sigParts.join("|"),
      sim_code: simCode,
      sim_label: simLabel,
      sim_badge_cls: simBadgeCls,
      cells,
    };
  }

  function computePeptideBiochem(seq, aaProps) {
    let gravySum = 0;
    let formalQ = 0;
    let arom = 0;
    let polar = 0;
    const groups = [];

    for (let i = 0; i < seq.length; i++) {
      const p = aaProps[seq[i]];
      gravySum += p.hydropathy;
      formalQ += p.charge;
      if (p.group === "Aromatic" || seq[i] === "H") arom++;
      if (["Polar", "Positive", "Negative"].includes(p.group)) polar++;
      groups.push(p.group);
    }

    const posPka = { K: 10.5, R: 12.5, H: 6.0 };
    const negPka = { D: 3.9, E: 4.1, C: 8.3, Y: 10.1 };

    function netChargeAtPh(ph) {
      let q = 1.0 / (1.0 + Math.pow(10, ph - 8.0));
      q -= 1.0 / (1.0 + Math.pow(10, 3.1 - ph));
      for (let i = 0; i < seq.length; i++) {
        const aa = seq[i];
        if (posPka[aa] !== undefined) {
          q += 1.0 / (1.0 + Math.pow(10, ph - posPka[aa]));
        } else if (negPka[aa] !== undefined) {
          q -= 1.0 / (1.0 + Math.pow(10, negPka[aa] - ph));
        }
      }
      return q;
    }

    const chargePh74 = Number(netChargeAtPh(7.4).toFixed(2));
    let lo = 0.0;
    let hi = 14.0;
    for (let iter = 0; iter < 40; iter++) {
      const mid = 0.5 * (lo + hi);
      if (netChargeAtPh(mid) > 0) lo = mid;
      else hi = mid;
    }
    const piVal = Number((0.5 * (lo + hi)).toFixed(2));

    return {
      gravy: Number((gravySum / seq.length).toFixed(2)),
      net_charge_ph74: chargePh74,
      formal_sidechain_charge: Number(formalQ.toFixed(1)),
      isoelectric_point: piVal,
      aromatic_count: arom,
      polar_count: polar,
      residue_groups: groups,
    };
  }

  function evaluateSeqleTiles(guessSeq, targetSeq, aaProps) {
    const evals = ["absent", "absent", "absent", "absent", "absent"];
    const remaining = targetSeq.split("");

    for (let i = 0; i < 5; i++) {
      if (guessSeq[i] === targetSeq[i]) {
        evals[i] = "exact";
        remaining[i] = null;
      }
    }

    for (let i = 0; i < 5; i++) {
      if (evals[i] !== "absent") continue;
      const ch = guessSeq[i];
      const idx = remaining.indexOf(ch);
      if (idx !== -1) {
        evals[i] = "present";
        remaining[idx] = null;
      }
    }

    for (let i = 0; i < 5; i++) {
      if (evals[i] === "absent") {
        if (aaProps[guessSeq[i]].group === aaProps[targetSeq[i]].group) {
          evals[i] = "class";
        }
      }
    }

    return evals;
  }

  function evaluateSeqleFeedbackFromSpec(guessSeq, targetSeq, aaProps, profileSpec, guessBiochem, targetBiochem) {
    let tiles = evaluateSeqleTiles(guessSeq, targetSeq, aaProps);
    if (profileSpec.show_positional_class_match === false) {
      tiles = tiles.map((t) => (t === "class" ? "absent" : t));
    }
    const gBio = guessBiochem || computePeptideBiochem(guessSeq, aaProps);
    const tBio = targetBiochem || computePeptideBiochem(targetSeq, aaProps);

    const stripCells = [];
    const sigParts = [tiles.map((t) => t[0].toUpperCase()).join("")];

    const stripSpecs = profileSpec.seqle_strip_fields || [];
    for (let i = 0; i < stripSpecs.length; i++) {
      const fSpec = stripSpecs[i];
      if (fSpec.shown === false) continue;
      const col = fSpec.name;
      const res = evaluateDeltaFromSpec(gBio[col], tBio[col], fSpec);
      if (guessSeq !== targetSeq) {
        sigParts.push(res.code);
      }
      stripCells.push({
        name: col,
        label: fSpec.label,
        decimals: fSpec.decimals !== undefined ? fSpec.decimals : 2,
        value: gBio[col],
        ...res,
      });
    }

    return {
      tiles,
      strip: stripCells,
      signature: sigParts.join("|"),
    };
  }

  function getGuessPool(data, mode) {
    // P0-3 Invariant: guessPool is ALWAYS the full catalog and never filtered by category/pack
    return mode === "chemle" ? data.chemle.slice() : data.seqle.slice();
  }

  function getAnswerPool(data, mode, profile, packFilter) {
    if (mode === "chemle") {
      const base = data.chemle.slice();
      if (profile === "ranked" || !packFilter || packFilter === "ALL") {
        return base;
      }
      const filtered = base.filter((m) => m.Category === packFilter);
      return filtered.length > 0 ? filtered : base;
    } else {
      return data.seqle.filter((m) => {
        const elig = Array.isArray(m.game_eligibility) ? m.game_eligibility : ["learn"];
        return elig.includes(profile);
      });
    }
  }

  function countCompatibleChemleCandidates(
    guesses,
    target,
    answerPool,
    simMatrix,
    profileSpec,
    chemById,
    clueConstraint
  ) {
    const gList = Array.isArray(guesses) ? guesses : [];
    if (gList.length === 0 && !clueConstraint) return answerPool.length;
    const profId = (clueConstraint && clueConstraint.profileId) || "learn";
    return answerPool.filter((cand) => {
      if (clueConstraint) {
        if (clueConstraint.level0Text) {
          const candLvl0 =
            cand.clue_ladder &&
            cand.clue_ladder[profId] &&
            cand.clue_ladder[profId][0] &&
            cand.clue_ladder[profId][0].text;
          if (candLvl0 !== clueConstraint.level0Text) return false;
        }
        if (clueConstraint.superClass !== undefined && clueConstraint.superClass !== null) {
          if (cand.super_class !== clueConstraint.superClass) return false;
        }
        if (clueConstraint.scaffoldUnlocked) {
          const candScaf = cand.scaffold_smiles || "";
          const targetScaf = clueConstraint.targetScaffoldSmiles || "";
          if (candScaf !== targetScaf) return false;
        }
      }
      for (let i = 0; i < gList.length; i++) {
        const gId = gList[i];
        const gObj = chemById[gId];
        if (!gObj) continue;
        if (gId !== target.id && cand.id === gId) return false;
        const obsSig = evaluateChemleFeedbackFromSpec(
          gObj,
          target,
          simMatrix[gId][target.id],
          profileSpec
        ).signature;
        const candSig = evaluateChemleFeedbackFromSpec(
          gObj,
          cand,
          simMatrix[gId][cand.id],
          profileSpec
        ).signature;
        if (obsSig !== candSig) return false;
      }
      return true;
    }).length;
  }

  function countCompatibleSeqleCandidates(
    guesses,
    target,
    answerPool,
    aaProps,
    profileSpec,
    clueConstraint
  ) {
    const gList = Array.isArray(guesses) ? guesses : [];
    if (gList.length === 0 && !clueConstraint) return answerPool.length;
    const profId = (clueConstraint && clueConstraint.profileId) || "learn";
    return answerPool.filter((cand) => {
      if (clueConstraint) {
        if (clueConstraint.level0Text) {
          const candLvl0 =
            cand.clue_ladder &&
            cand.clue_ladder[profId] &&
            cand.clue_ladder[profId][0] &&
            cand.clue_ladder[profId][0].text;
          if (candLvl0 !== clueConstraint.level0Text) return false;
        }
        if (clueConstraint.level1Text) {
          const candLvl1 =
            cand.clue_ladder &&
            cand.clue_ladder[profId] &&
            cand.clue_ladder[profId][1] &&
            cand.clue_ladder[profId][1].text;
          if (candLvl1 !== clueConstraint.level1Text) return false;
        }
      }
      for (let i = 0; i < gList.length; i++) {
        const gSeq = gList[i].seq;
        if (gSeq !== target.seq && cand.seq === gSeq) return false;
        const obsSig = evaluateSeqleFeedbackFromSpec(
          gSeq,
          target.seq,
          aaProps,
          profileSpec,
          gList[i].biochem,
          target
        ).signature;
        const candSig = evaluateSeqleFeedbackFromSpec(
          gSeq,
          cand.seq,
          aaProps,
          profileSpec,
          gList[i].biochem,
          cand
        ).signature;
        if (obsSig !== candSig) return false;
      }
      return true;
    }).length;
  }

  function evaluateDailyWinStreak(statsObj, game, utcDateStr) {
    const next = JSON.parse(JSON.stringify(statsObj));
    if (!next.lastDailyWinUtcByGame) {
      next.lastDailyWinUtcByGame = { chemle: null, seqle: null };
    }
    const alreadyWonThisGameToday = next.lastDailyWinUtcByGame[game] === utcDateStr;
    if (!alreadyWonThisGameToday) {
      if (game === "chemle") next.chemWins = (next.chemWins || 0) + 1;
      if (game === "seqle") next.seqWins = (next.seqWins || 0) + 1;
      next.lastDailyWinUtcByGame[game] = utcDateStr;
    }

    if (next.lastStreakIncrementUtc === utcDateStr) {
      // Already incremented streak today (e.g., won the other game earlier today or replayed)
      return next;
    }

    const prevUtc = getPreviousUtcDateString(utcDateStr);
    if (next.lastStreakIncrementUtc === prevUtc) {
      next.streak = (next.streak || 0) + 1;
    } else {
      next.streak = 1;
    }
    next.maxStreak = Math.max(next.maxStreak || 0, next.streak);
    next.lastStreakIncrementUtc = utcDateStr;
    return next;
  }

  function migrateV1Stats(v1) {
    const src = v1 && typeof v1 === "object" ? v1 : {};
    return {
      schema: 2,
      chemWins: Math.max(0, Number(src.chemWins) || 0),
      seqWins: Math.max(0, Number(src.seqWins) || 0),
      streak: 0,
      maxStreak: 0,
      lastDailyWinUtcByGame: { chemle: null, seqle: null },
      lastStreakIncrementUtc: null,
    };
  }

  const BioWordleEngine = {
    fnv1aHash,
    getUtcDateString,
    getPreviousUtcDateString,
    selectDailyIndex,
    evaluateDeltaFromSpec,
    evaluateChemleFeedbackFromSpec,
    computePeptideBiochem,
    evaluateSeqleTiles,
    evaluateSeqleFeedbackFromSpec,
    getGuessPool,
    getAnswerPool,
    countCompatibleChemleCandidates,
    countCompatibleSeqleCandidates,
    evaluateDailyWinStreak,
    migrateV1Stats,
  };

  globalScope.BioWordleEngine = BioWordleEngine;
  if (typeof module !== "undefined" && module.exports) {
    module.exports = BioWordleEngine;
  }

  // Stop here if running in headless Node without a DOM document
  if (typeof document === "undefined" || !globalScope.BIOWORDLE_DATA) {
    return;
  }

  // ---------------------------------------------------------------------------
  // 2. Browser Application State & Persistence (P1-2)
  // ---------------------------------------------------------------------------
  const DATA = globalScope.BIOWORDLE_DATA;
  const FEEDBACK_SPEC = DATA.feedback_spec;
  const DATASET_HASH = (DATA.metadata && DATA.metadata.dataset_version_hash) || "v02";
  const SCHEDULE_HASH = (DATA.metadata && DATA.metadata.schedule_version_hash) || DATASET_HASH;

  const CHEM_BY_ID = {};
  DATA.chemle.forEach((m) => {
    CHEM_BY_ID[m.id] = m;
  });

  const SEQ_BY_CODE = {};
  DATA.seqle.forEach((s) => {
    SEQ_BY_CODE[s.seq] = s;
  });

  const STATS_KEY_V2 = "biowordle_stats_v2";
  const STATS_KEY_V1 = "biowordle_stats_v1";

  function loadStatsV2() {
    try {
      const rawV2 = localStorage.getItem(STATS_KEY_V2);
      if (rawV2) {
        const parsed = JSON.parse(rawV2);
        if (parsed && parsed.schema === 2) return parsed;
      }
      const rawV1 = localStorage.getItem(STATS_KEY_V1);
      if (rawV1) {
        const v1 = JSON.parse(rawV1);
        const migrated = migrateV1Stats(v1);
        localStorage.setItem(STATS_KEY_V2, JSON.stringify(migrated));
        return migrated;
      }
    } catch (_) {}
    return {
      schema: 2,
      chemWins: 0,
      seqWins: 0,
      streak: 0,
      maxStreak: 0,
      lastDailyWinUtcByGame: { chemle: null, seqle: null },
      lastStreakIncrementUtc: null,
    };
  }

  function saveStatsV2(statsObj) {
    try {
      localStorage.setItem(STATS_KEY_V2, JSON.stringify(statsObj));
    } catch (_) {}
  }

  function getDailyStorageKey(game, utcDate, customSeed) {
    if (customSeed) {
      return `biowordle_seed_v2:${game}:${customSeed}:${SCHEDULE_HASH}`;
    }
    return `biowordle_daily_v2:${game}:${utcDate}:${SCHEDULE_HASH}`;
  }

  function getLegacyDailyStorageKey(game, utcDate, customSeed) {
    if (customSeed) {
      return `biowordle_seed_v2:${game}:${customSeed}:${DATASET_HASH}`;
    }
    return `biowordle_daily_v2:${game}:${utcDate}:${DATASET_HASH}`;
  }

  function loadPersistedDailyGame(game, utcDate, customSeed) {
    try {
      const raw = localStorage.getItem(getDailyStorageKey(game, utcDate, customSeed));
      if (raw) return JSON.parse(raw);
      if (SCHEDULE_HASH !== DATASET_HASH) {
        const legacyRaw = localStorage.getItem(getLegacyDailyStorageKey(game, utcDate, customSeed));
        if (legacyRaw) return JSON.parse(legacyRaw);
      }
      return null;
    } catch (_) {
      return null;
    }
  }

  function savePersistedDailyGame(game, utcDate, customSeed, payload) {
    try {
      localStorage.setItem(getDailyStorageKey(game, utcDate, customSeed), JSON.stringify(payload));
    } catch (_) {}
  }

  // Parse optional ?seed=<string> or ?profile=learn from URL (P3-1)
  function parseUrlParams() {
    try {
      const params = new URLSearchParams(globalScope.location.search || "");
      return {
        seed: params.get("seed") ? params.get("seed").trim() : null,
        profile: params.get("profile") === "learn" ? "learn" : "ranked",
      };
    } catch (_) {
      return { seed: null, profile: "ranked" };
    }
  }

  const urlCfg = parseUrlParams();

  function createBlankChemleSession() {
    return {
      target: null,
      guesses: [],
      maxGuesses: 6,
      hintLevelUnlocked: 0,
      revealed: false,
      won: false,
      activeDropdownIdx: -1,
      filteredOptions: [],
      utcDate: null,
      initialized: false,
    };
  }

  function createBlankSeqleSession() {
    return {
      target: null,
      guesses: [],
      currentInput: "",
      maxGuesses: 6,
      hintLevelUnlocked: 0,
      revealed: false,
      won: false,
      keyStates: {},
      utcDate: null,
      initialized: false,
    };
  }

  const state = {
    mode: "chemle", // 'chemle' | 'seqle'
    profile: urlCfg.profile, // 'ranked' | 'learn'
    customSeed: urlCfg.seed,
    learnCategoryFilter: "ALL",
    stats: loadStatsV2(),
    sessions: {
      ranked: {
        chemle: createBlankChemleSession(),
        seqle: createBlankSeqleSession(),
      },
      learn: {
        chemle: createBlankChemleSession(),
        seqle: createBlankSeqleSession(),
      },
    },
  };

  function activeChemle() {
    return state.sessions[state.profile].chemle;
  }

  function activeSeqle() {
    return state.sessions[state.profile].seqle;
  }

  function activeProfileSpec() {
    return FEEDBACK_SPEC.profiles[state.profile];
  }

  // ---------------------------------------------------------------------------
  // 3. DOM Utilities & Topbar Synchronization
  // ---------------------------------------------------------------------------
  const $ = (id) => document.getElementById(id);

  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function formatFormula(f) {
    return String(f).replace(/(\d+)/g, "<sub>$1</sub>");
  }

  function updateScoreboardUI() {
    $("stat-chem").textContent = state.stats.chemWins || 0;
    $("stat-seq").textContent = state.stats.seqWins || 0;
    $("stat-streak").textContent = state.stats.streak || 0;
  }

  function showUtcRolloverNotice(prevUtc, nextUtc) {
    const el = $("utc-rollover-banner");
    if (!el) return;
    el.className = "toast-banner show";
    el.innerHTML = `
      <div>🕒 <strong>UTC Midnight Rollover:</strong> Daily date advanced from <code>${escapeHtml(prevUtc)}</code> to <code>${escapeHtml(nextUtc)}</code>. Fresh Ranked daily puzzles have been loaded.</div>
      <button class="btn" onclick="this.closest('.toast-banner').classList.remove('show')">Dismiss</button>
    `;
  }

  function checkAndHandleUtcRollover() {
    if (state.customSeed) return false;
    const currentUtc = getUtcDateString();
    const rChem = state.sessions.ranked.chemle;
    const rSeq = state.sessions.ranked.seqle;
    const staleChem = Boolean(rChem.initialized && rChem.utcDate && rChem.utcDate !== currentUtc);
    const staleSeq = Boolean(rSeq.initialized && rSeq.utcDate && rSeq.utcDate !== currentUtc);
    if (!staleChem && !staleSeq) return false;

    const prevUtc = (staleChem ? rChem.utcDate : rSeq.utcDate) || "";
    rChem.initialized = false;
    rSeq.initialized = false;
    ensureSessionInitialized("chemle", "ranked", false);
    ensureSessionInitialized("seqle", "ranked", false);

    if (state.profile === "ranked") {
      showUtcRolloverNotice(prevUtc, currentUtc);
      syncHeaderAndProfileControls();
      if (state.mode === "chemle") renderChemleView();
      else renderSeqleView();
    }
    return true;
  }

  function updateUtcCountdownUI() {
    checkAndHandleUtcRollover();
    const el = $("utc-countdown");
    if (!el) return;
    const now = new Date();
    const nextMidnight = Date.UTC(
      now.getUTCFullYear(),
      now.getUTCMonth(),
      now.getUTCDate() + 1,
      0,
      0,
      0
    );
    const diffSec = Math.max(0, Math.floor((nextMidnight - now.getTime()) / 1000));
    const hh = String(Math.floor(diffSec / 3600)).padStart(2, "0");
    const mm = String(Math.floor((diffSec % 3600) / 60)).padStart(2, "0");
    const ss = String(diffSec % 60).padStart(2, "0");
    el.textContent = `(UTC ${hh}:${mm}:${ss})`;
  }

  function syncHintButtonUI() {
    const hintBtn = $("btn-hint");
    if (!hintBtn) return;
    if (state.profile === "ranked") {
      hintBtn.disabled = true;
      hintBtn.textContent = "🔒 Auto-Clues (Ranked)";
      hintBtn.title = "Ranked mode unlocks clues automatically by guess count only; manual hints are disabled.";
      return;
    }
    const curSess = state.mode === "chemle" ? activeChemle() : activeSeqle();
    const curLvl = curSess && curSess.target ? getUnlockedClueLevel(curSess, "learn") : 0;
    hintBtn.disabled = Boolean(curSess && (curSess.revealed || curLvl >= 3));
    hintBtn.textContent = "💡 Hint";
    hintBtn.title = "Unlock next clue in the progressive Clue Ladder";
  }

  function syncHeaderAndProfileControls() {
    const isRanked = state.profile === "ranked";
    const playBtn = $("btn-playstyle");
    if (state.customSeed && isRanked) {
      playBtn.textContent = `🎓 Seed: ${state.customSeed}`;
    } else {
      playBtn.textContent = isRanked ? "🏆 Profile: Ranked (UTC)" : "🎓 Profile: Learn (Pack)";
    }
    playBtn.classList.toggle("btn-primary", isRanked);

    const rndBtn = $("btn-new-puzzle");
    rndBtn.disabled = isRanked && !state.customSeed;
    rndBtn.title = isRanked
      ? "Ranked Daily uses a single canonical UTC puzzle per day. Switch to Learn Mode to roll random practice puzzles."
      : "Roll a random new puzzle from the active Learn answer pool";

    syncHintButtonUI();

    const seqCountBadge = $("badge-seqle-count");
    if (seqCountBadge) {
      const ansPool = getAnswerPool(DATA, "seqle", state.profile, state.learnCategoryFilter);
      seqCountBadge.textContent = isRanked ? `${ansPool.length} Ranked` : `${ansPool.length} Motifs`;
    }

    const chemProfBadge = $("chemle-profile-badge");
    const seqProfBadge = $("seqle-profile-badge");
    const badgeLabel = isRanked
      ? state.customSeed
        ? `🎓 Classroom Seed (${state.customSeed})`
        : "🏆 Ranked Profile"
      : "🎓 Learn Profile";
    if (chemProfBadge) {
      chemProfBadge.textContent = badgeLabel;
      chemProfBadge.className = `badge ${isRanked ? "badge-amber" : "badge-emerald"}`;
    }
    if (seqProfBadge) {
      seqProfBadge.textContent = badgeLabel;
      seqProfBadge.className = `badge ${isRanked ? "badge-amber" : "badge-emerald"}`;
    }

    populateCategoryFilterDropdown();
    populateSeqleMotifPicker();
  }

  function populateCategoryFilterDropdown() {
    const sel = $("chemle-cat-filter");
    if (!sel) return;
    if (state.profile === "ranked") {
      sel.innerHTML = `<option value="ALL">All Categories (Ranked Daily Pool: ${DATA.chemle.length})</option>`;
      sel.value = "ALL";
      sel.disabled = true;
      sel.title =
        "Category pack filtering is disabled in Ranked Daily so the daily answer is never excluded. All 36 molecules remain searchable.";
      return;
    }

    sel.disabled = false;
    sel.title =
      "In Learn Mode, selecting a pack restricts the target answer pool while keeping all 36 molecules available as probing guesses.";
    const counts = {};
    DATA.chemle.forEach((m) => {
      counts[m.Category] = (counts[m.Category] || 0) + 1;
    });
    const cats = Object.keys(counts).sort();
    sel.innerHTML =
      `<option value="ALL">All Answer Packs (${DATA.chemle.length} Mols)</option>` +
      cats
        .map((c) => `<option value="${escapeHtml(c)}">${escapeHtml(c)} (${counts[c]})</option>`)
        .join("");
    sel.value = state.learnCategoryFilter || "ALL";
  }

  function populateSeqleMotifPicker() {
    const picker = $("seqle-motif-picker");
    if (!picker) return;
    // P0-3: All 30 motifs are always in guessPool and available to probe!
    const allMotifs = getGuessPool(DATA, "seqle");
    picker.innerHTML =
      `<option value="">— Quick-fill from all ${allMotifs.length} curated 5-AA motifs (or type any 5 standard AAs) —</option>` +
      allMotifs
        .map((m) => {
          const isLearnOnly = !Array.isArray(m.game_eligibility) || !m.game_eligibility.includes("ranked");
          const tag = isLearnOnly ? " [Learn Abstraction]" : m.kind === "fragment" ? " [5-mer Window]" : "";
          return `<option value="${m.seq}">${m.seq} · ${escapeHtml(m.family)}${tag}</option>`;
        })
        .join("");
  }

  // ---------------------------------------------------------------------------
  // 4. Session Initialization & Restore (P0-3, P1-2, P1-3)
  // ---------------------------------------------------------------------------
  function ensureSessionInitialized(game, profile, forceNewRandom) {
    const sess = state.sessions[profile][game];
    if (sess.initialized && !forceNewRandom) {
      return;
    }

    const ansPool = getAnswerPool(DATA, game, profile, state.learnCategoryFilter);
    const guessPool = getGuessPool(DATA, game);
    const utcDate = getUtcDateString();

    if (profile === "ranked") {
      const idx = selectDailyIndex(
        game,
        profile,
        utcDate,
        SCHEDULE_HASH,
        ansPool.length,
        state.customSeed
      );
      const target = ansPool[idx];

      // P0-3 Runtime Invariant: target MUST exist in guessPool
      const inGuessPool = guessPool.some((x) => (x.id || x.seq) === (target.id || target.seq));
      if (!inGuessPool) {
        throw new Error(`[P0-3 Invariant Violation] Target ${target.id || target.seq} missing from guessPool!`);
      }

      sess.target = target;
      sess.guesses = [];
      sess.hintLevelUnlocked = 0;
      sess.revealed = false;
      sess.won = false;
      sess.utcDate = utcDate;
      if (game === "seqle") {
        sess.currentInput = "";
        sess.keyStates = {};
      }

      // Restore persisted daily progress if present (P1-2)
      const saved = loadPersistedDailyGame(game, utcDate, state.customSeed);
      const targetKey = game === "chemle" ? target.id : target.seq;
      if (saved && saved.targetId === targetKey && Array.isArray(saved.guesses)) {
        if (game === "chemle") {
          sess.guesses = saved.guesses.filter((gId) => Boolean(CHEM_BY_ID[gId]));
        } else {
          sess.guesses = saved.guesses.map((gSeq) => {
            const code = typeof gSeq === "string" ? gSeq : gSeq.seq;
            const known = SEQ_BY_CODE[code];
            const biochem = known ? known : computePeptideBiochem(code, DATA.aa_properties);
            const evalRes = evaluateSeqleFeedbackFromSpec(
              code,
              target.seq,
              DATA.aa_properties,
              FEEDBACK_SPEC.profiles.ranked,
              biochem,
              target
            );
            const prio = { exact: 4, present: 3, class: 2, absent: 1 };
            for (let i = 0; i < 5; i++) {
              const aa = code[i];
              const st = evalRes.tiles[i];
              const cur = sess.keyStates[aa];
              if (!cur || prio[st] > prio[cur]) sess.keyStates[aa] = st;
            }
            return {
              seq: code,
              states: evalRes.tiles,
              biochem,
              knownMotif: known || null,
            };
          });
        }
        sess.won = Boolean(saved.won);
        sess.revealed = Boolean(saved.gameOver);
        sess.hintLevelUnlocked = 0;
      }
      sess.initialized = true;
    } else {
      // Learn Mode: pick a random puzzle from the active Learn answer pool
      const prevKey = sess.target ? sess.target.id || sess.target.seq : null;
      let candidates = ansPool.filter((m) => (m.id || m.seq) !== prevKey);
      if (candidates.length === 0) candidates = ansPool;
      const target = candidates[Math.floor(Math.random() * candidates.length)];

      const inGuessPool = guessPool.some((x) => (x.id || x.seq) === (target.id || target.seq));
      if (!inGuessPool) {
        throw new Error(`[P0-3 Invariant Violation] Target ${target.id || target.seq} missing from guessPool!`);
      }

      sess.target = target;
      sess.guesses = [];
      sess.hintLevelUnlocked = 0;
      sess.revealed = false;
      sess.won = false;
      sess.utcDate = null;
      if (game === "seqle") {
        sess.currentInput = "";
        sess.keyStates = {};
      }
      sess.initialized = true;
    }
  }

  function persistCurrentRankedState(game) {
    if (state.profile !== "ranked") return;
    const sess = state.sessions.ranked[game];
    if (!sess || !sess.target) return;
    const utcDate = sess.utcDate || getUtcDateString();
    const targetId = game === "chemle" ? sess.target.id : sess.target.seq;
    const serializedGuesses =
      game === "chemle" ? sess.guesses.slice() : sess.guesses.map((g) => g.seq);
    savePersistedDailyGame(game, utcDate, state.customSeed, {
      targetId,
      guesses: serializedGuesses,
      won: sess.won,
      gameOver: sess.revealed,
      hintLevelUnlocked: 0,
      utcDate,
      scheduleHash: SCHEDULE_HASH,
      datasetHash: DATASET_HASH,
    });
  }

  // ---------------------------------------------------------------------------
  // 5. CHEMLE Rendering & Gameplay (P0-1, P0-3, P1-1, P3-3)
  // ---------------------------------------------------------------------------
  function renderChemleView() {
    const ch = activeChemle();
    const t = ch.target;
    const profSpec = activeProfileSpec();
    const ansPool = getAnswerPool(DATA, "chemle", state.profile, state.learnCategoryFilter);
    const maxLvl = getUnlockedClueLevel(ch, state.profile);
    const ladder = (t.clue_ladder && t.clue_ladder[state.profile]) || [];
    const scafThreshold = Number((profSpec && profSpec.scaffold_unlock_after_guesses) || 3);
    const clueConstraint = {
      profileId: state.profile,
      level0Text: ladder[0] ? ladder[0].text : null,
      superClass: maxLvl >= 1 ? t.super_class : null,
      scaffoldUnlocked:
        (state.profile === "learn" && maxLvl >= 1) ||
        (state.profile === "ranked" && ch.guesses.length >= scafThreshold),
      targetScaffoldSmiles: t.scaffold_smiles || "",
    };

    syncHintButtonUI();
    $("chemle-try-counter").textContent = `Guesses: ${ch.guesses.length} / ${ch.maxGuesses}`;
    const compat = countCompatibleChemleCandidates(
      ch.guesses,
      t,
      ansPool,
      DATA.chemle_similarity,
      profSpec,
      CHEM_BY_ID,
      clueConstraint
    );
    $("chemle-candidates-pill").textContent = `Candidates: ${compat} / ${ansPool.length}`;

    // Banner state
    const banner = $("chemle-banner");
    if (ch.won) {
      banner.className = "toast-banner show win";
      banner.innerHTML = `
        <div>🎉 <strong>Solved in ${ch.guesses.length}/${ch.maxGuesses}!</strong> The target molecule is <strong>${escapeHtml(t.name)}</strong> (${formatFormula(t.Formula)}).</div>
        <div style="display:flex;gap:6px;">
          <button class="btn" onclick="window.__bwCopyShare()">📋 Share</button>
          ${state.profile === "learn" ? `<button class="btn btn-primary" onclick="window.__bwNewPuzzle()">Next Molecule →</button>` : ""}
        </div>
      `;
    } else if (ch.revealed) {
      banner.className = "toast-banner show lose";
      banner.innerHTML = `
        <div>🔬 <strong>Target Revealed:</strong> <strong>${escapeHtml(t.name)}</strong> (${formatFormula(t.Formula)}) — ${escapeHtml(t.Category)}.</div>
        <div style="display:flex;gap:6px;">
          <button class="btn" onclick="window.__bwCopyShare()">📋 Share</button>
          ${state.profile === "learn" ? `<button class="btn btn-primary" onclick="window.__bwNewPuzzle()">Try Another →</button>` : ""}
        </div>
      `;
    } else {
      banner.className = "toast-banner";
      banner.innerHTML = "";
    }

    renderChemleInspector();
    renderChemleGuesses();
  }

  function getUnlockedClueLevel(sess, profileOverride) {
    if (sess.revealed) return 3;
    const prof = profileOverride || state.profile;
    const ladder = (sess.target.clue_ladder && sess.target.clue_ladder[prof]) || [];
    let autoLevel = 0;
    for (let i = 0; i < ladder.length; i++) {
      if (sess.guesses.length >= ladder[i].after_guesses) {
        autoLevel = Math.max(autoLevel, ladder[i].level);
      }
    }
    if (prof === "ranked") {
      return Math.min(3, autoLevel);
    }
    return Math.min(3, Math.max(autoLevel, sess.hintLevelUnlocked || 0));
  }

  function renderChemleInspector() {
    const ch = activeChemle();
    const t = ch.target;
    const well = $("chemle-structure-well");
    const stageBadge = $("chemle-clue-stage");
    const hintsList = $("chemle-hints-list");
    const fullProps = $("chemle-full-props");

    const maxLvl = getUnlockedClueLevel(ch, state.profile);
    const ladder = (t.clue_ladder && t.clue_ladder[state.profile]) || [];
    const profSpec = activeProfileSpec();
    const scafThreshold = Number((profSpec && profSpec.scaffold_unlock_after_guesses) || 3);
    const scafUnlocked =
      !ch.revealed &&
      ((state.profile === "learn" && maxLvl >= 1) ||
        (state.profile === "ranked" && ch.guesses.length >= scafThreshold));

    // 2D SVG well (Silhouette -> Scaffold -> Full Revealed)
    const showScaffold = t.has_scaffold && scafUnlocked;

    if (ch.revealed) {
      well.className = "chem-svg-well";
      well.innerHTML = t.svg_full + `<span class="well-overlay-tag">${escapeHtml(t.name)}</span>`;
      stageBadge.textContent = "Revealed";
      stageBadge.className = "badge badge-emerald";
    } else if (showScaffold) {
      well.className = "chem-svg-well";
      const scLabel =
        t.scaffold_mode === "bemis_murcko"
          ? "Bemis–Murcko Ring Scaffold"
          : "Anonymized Carbon Skeleton";
      well.innerHTML = t.svg_scaffold + `<span class="well-overlay-tag">${scLabel}</span>`;
      stageBadge.textContent = `Level ${maxLvl} · Scaffold`;
      stageBadge.className = "badge badge-amber";
    } else {
      well.className = "chem-svg-well silhouette";
      well.innerHTML =
        t.svg_scaffold + `<span class="well-overlay-tag">2D Silhouette (Hidden)</span>`;
      stageBadge.textContent = `Level ${maxLvl} · ${maxLvl === 0 ? "k-Anonymous" : "Clues Active"}`;
      stageBadge.className = "badge badge-indigo";
    }

    // Progressive Clue Ladder (P0-1: No exact MW, no exact Category, no IG bits pre-guess!)
    const visibleClues = ladder.filter((item) => item.level <= maxLvl);
    let html = visibleClues
      .map(
        (c) => `
        <div class="hint-item">
          <strong>${escapeHtml(c.title)}</strong>
          ${escapeHtml(c.text)}
        </div>`
      )
      .join("");

    if (!ch.revealed && maxLvl < 3) {
      const nextClue = ladder.find((c) => c.level === maxLvl + 1);
      if (nextClue) {
        const unlockMsg =
          state.profile === "ranked"
            ? `Auto-unlocks after Guess ${nextClue.after_guesses}`
            : `Click 💡 Hint to unlock ${nextClue.title}`;
        html += `
          <div class="hint-item" style="opacity:0.75;border-style:dashed;">
            <strong>Locked · ${escapeHtml(nextClue.title)}</strong>
            ${escapeHtml(unlockMsg)}
          </div>`;
      }
    }

    if (!ch.revealed && !t.has_scaffold && scafUnlocked) {
      html += `
        <div class="hint-item">
          <strong>Topology Note</strong>
          This molecule is acyclic (Rings = 0), so no cyclic Bemis–Murcko scaffold preview applies.
        </div>`;
    }

    hintsList.innerHTML = html;

    // Post-Game Panel ONLY: Full Descriptors, Exact Category, Opening-Probe Quality, and Similarity Explorer
    if (ch.revealed) {
      fullProps.style.display = "block";
      const alertBadges =
        t.Alerts && t.Alerts.length
          ? t.Alerts.map((a) => `<span class="badge badge-rose">${escapeHtml(a)}</span>`).join(" ")
          : `<span class="badge badge-emerald">None (Clean)</span>`;

      const stdBadge = t.standardization_changed
        ? `<span class="badge badge-amber">Normalized (${escapeHtml(t.standardization_steps.join(", "))})</span>`
        : `<span class="badge badge-emerald">Unchanged (Input = Game Species)</span>`;

      const probeQual =
        (t.opening_probe_quality && t.opening_probe_quality[state.profile]) || {
          information_gain_bits: t.information_gain_bits,
          expected_remaining_candidates: t.expected_remaining_candidates,
          difficulty_tier: t.difficulty_tier,
        };

      // Top-5 Tanimoto neighbors for Post-Game Similarity Explorer (P3-3)
      const simMap = DATA.chemle_similarity[t.id] || {};
      const topNeighbors = DATA.chemle
        .filter((m) => m.id !== t.id)
        .map((m) => ({ mol: m, sim: simMap[m.id] || 0 }))
        .sort((a, b) => b.sim - a.sim)
        .slice(0, 5);

      // Best opening probe across the catalog for this profile
      const bestOpeningMol = DATA.chemle
        .slice()
        .sort((a, b) => {
          const qa =
            (a.opening_probe_quality && a.opening_probe_quality[state.profile]) || {};
          const qb =
            (b.opening_probe_quality && b.opening_probe_quality[state.profile]) || {};
          return (qb.information_gain_bits || 0) - (qa.information_gain_bits || 0);
        })[0];
      const bestProbeQual =
        (bestOpeningMol.opening_probe_quality &&
          bestOpeningMol.opening_probe_quality[state.profile]) ||
        {};

      fullProps.innerHTML = `
        <div class="hint-item" style="margin-top:8px;">
          <strong>Structural &amp; Stereochemical Note</strong>
          ${escapeHtml(t.structural_note)}
        </div>
        <div class="prop-grid">
          <div class="prop-cell"><span class="prop-label">Category</span><span class="prop-val">${escapeHtml(t.Category)}</span></div>
          <div class="prop-cell"><span class="prop-label">Formula</span><span class="prop-val">${formatFormula(t.Formula)}</span></div>
          <div class="prop-cell"><span class="prop-label">Exact MW</span><span class="prop-val">${t.MW} Da</span></div>
          <div class="prop-cell"><span class="prop-label">cLogP</span><span class="prop-val">${t.cLogP}</span></div>
          <div class="prop-cell"><span class="prop-label">TPSA</span><span class="prop-val">${t.TPSA} Å²</span></div>
          <div class="prop-cell"><span class="prop-label">Fsp³</span><span class="prop-val">${t.Fsp3}</span></div>
          <div class="prop-cell"><span class="prop-label">Chiral Ctrs</span><span class="prop-val">${t.ChiralCenters}</span></div>
          <div class="prop-cell"><span class="prop-label">QED</span><span class="prop-val">${t.QED}</span></div>
          <div class="prop-cell"><span class="prop-label">SA Score</span><span class="prop-val">${t.SA_Score}</span></div>
        </div>
        <div class="hint-item" style="margin-top:8px;">
          <strong>Post-Game Opening-Probe Quality (${escapeHtml(state.profile.toUpperCase())})</strong>
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px;font-size:11px;">
            <span class="badge badge-indigo">Opening IG: ${probeQual.information_gain_bits} bits</span>
            <span class="badge badge-cyan">Expected Remaining: ${probeQual.expected_remaining_candidates} mols</span>
            <span class="badge badge-emerald">Tier: ${escapeHtml(probeQual.difficulty_tier || t.difficulty_tier)}</span>
          </div>
          <div style="margin-top:5px;font-size:11px;color:var(--muted-foreground);">
            💡 <b>Solver Coach:</b> Highest-entropy opening probe in <code>${escapeHtml(state.profile)}</code> is <b>${escapeHtml(bestOpeningMol.name)}</b> (IG ${bestProbeQual.information_gain_bits} bits, leaving ${bestProbeQual.expected_remaining_candidates} expected candidates).
          </div>
        </div>
        <div class="hint-item" style="margin-top:8px;">
          <strong>Closest Chiral ECFP4 Neighbors in Catalog</strong>
          <div class="fg-chips" style="margin-top:5px;">
            ${topNeighbors
              .map(
                (n) =>
                  `<span class="fg-chip">${escapeHtml(n.mol.name)}: <b>${n.sim}%</b></span>`
              )
              .join("")}
          </div>
        </div>
        <div class="hint-item" style="margin-top:8px;">
          <strong>Post-Game MedChem &amp; Standardization Audit</strong>
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px;font-size:11px;">
            <span title="${escapeHtml(t.CNS_MPO_Method)}">4-Prop CNS-MPO Approx: <b>${t.CNS_MPO_4prop} / 4.0</b></span>
            <span>Lipinski: <b>${t.Lipinski_Violations} viol.</b></span>
            <span>Alerts: ${alertBadges}</span>
          </div>
          <div style="margin-top:6px;font-size:10.5px;color:var(--muted-foreground);word-break:break-all;">
            <div><b>Standardization:</b> ${stdBadge}</div>
            <div><b>InChIKey:</b> <code>${escapeHtml(t.inchikey)}</code> · <b>SVG SHA-256:</b> <code>${escapeHtml(t.svg_sha256)}</code></div>
            <div><b>Canonical SMILES:</b> <code>${escapeHtml(t.canonical_smiles)}</code></div>
          </div>
        </div>
      `;
    } else {
      fullProps.style.display = "none";
      fullProps.innerHTML = "";
    }
  }

  function renderChemleGuesses() {
    const ch = activeChemle();
    const t = ch.target;
    const profSpec = activeProfileSpec();
    const container = $("chemle-guesses");

    if (ch.guesses.length === 0) {
      container.innerHTML = `
        <div class="hint-item" style="text-align:center;padding:18px;color:var(--muted-foreground);">
          Type or select any of the <strong>36 curated molecules</strong> above to make your first guess.<br/>
          <small>In <strong>${escapeHtml(state.profile.toUpperCase())}</strong> profile, each guess compares ${(profSpec.chemle_fields || []).map((f) => f.label).join(", ")} and Chiral Morgan Tanimoto similarity.</small>
        </div>
      `;
      return;
    }

    const cardsHtml = ch.guesses
      .slice()
      .reverse()
      .map((gId, revIdx) => {
        const guessNum = ch.guesses.length - revIdx;
        const g = CHEM_BY_ID[gId];
        const isWin = g.inchikey === t.inchikey;
        const sim = DATA.chemle_similarity[g.id][t.id];
        const fb = evaluateChemleFeedbackFromSpec(g, t, sim, profSpec);

        const simText = profSpec.show_exact_tanimoto
          ? `${sim}% (${fb.sim_label})`
          : fb.sim_label;

        const fieldCellsHtml = fb.cells
          .map((cell) => {
            return `
              <div class="delta-cell ${cell.cls}">
                <span class="prop-label">${escapeHtml(cell.label)}</span>
                <span class="prop-val">${escapeHtml(String(cell.value))} <span class="delta-arrow">${cell.arrow}</span></span>
              </div>
            `;
          })
          .join("");

        let fgFooterHtml = "";
        if (profSpec.show_functional_groups_live || ch.revealed) {
          const tFgSet = new Set(t.functional_groups || []);
          const fgChips = (g.functional_groups || [])
            .map((fg) => {
              const shared = tFgSet.has(fg);
              return `<span class="fg-chip ${shared ? "shared" : ""}">${shared ? "✓ " : ""}${escapeHtml(fg)}</span>`;
            })
            .join("");
          fgFooterHtml = `<div class="fg-chips" title="Green chips are functional groups also present in the target molecule">${fgChips}</div>`;
        } else {
          const fgChips = (g.functional_groups || [])
            .map((fg) => `<span class="fg-chip">${escapeHtml(fg)}</span>`)
            .join("");
          fgFooterHtml = `<div class="fg-chips" title="Guess functional groups (shared target overlap unlocks in Learn Mode or upon reveal)">${fgChips}</div>`;
        }

        return `
        <div class="chemle-guess-card">
          <div class="chemle-guess-top">
            <div class="chemle-guess-name">
              <span class="badge badge-indigo">#${guessNum}</span>
              <span>${escapeHtml(g.name)}</span>
              <span style="font-size:11.5px;color:var(--muted-foreground);font-weight:500;">${formatFormula(g.Formula)}</span>
              ${isWin ? `<span class="badge badge-emerald">✓ Exact Match (InChIKey)</span>` : ""}
            </div>
            <div style="display:flex;gap:6px;align-items:center;">
              <span class="badge ${g.Category === t.Category && ch.revealed ? "badge-emerald" : "badge-cyan"}">${escapeHtml(g.Category)}</span>
              <span class="badge ${fb.sim_badge_cls}"
                    title="Chiral Morgan Fingerprint (ECFP4-like, radius=2, 2048 bits) Tanimoto Similarity">
                Tanimoto: ${escapeHtml(simText)}
              </span>
            </div>
          </div>

          <div class="chemle-Compare-grid">
            <div class="mini-svg-well" title="${escapeHtml(g.name)}">${g.svg_full}</div>
            ${fieldCellsHtml}
          </div>

          ${fgFooterHtml}
        </div>
      `;
      })
      .join("");

    container.innerHTML = cardsHtml;
  }

  function submitChemleGuess(molId) {
    if (state.profile === "ranked" && checkAndHandleUtcRollover()) {
      $("chemle-search-input").value = "";
      closeChemleDropdown();
      return;
    }
    const ch = activeChemle();
    if (ch.revealed || ch.won) return;
    if (!CHEM_BY_ID[molId]) return;
    if (ch.guesses.includes(molId)) return;

    ch.guesses.push(molId);
    const g = CHEM_BY_ID[molId];
    if (g.inchikey === ch.target.inchikey) {
      ch.won = true;
      ch.revealed = true;
      if (state.profile === "ranked" && !state.customSeed) {
        state.stats = evaluateDailyWinStreak(state.stats, "chemle", ch.utcDate || getUtcDateString());
      } else {
        state.stats.chemWins = (state.stats.chemWins || 0) + 1;
      }
      saveStatsV2(state.stats);
      updateScoreboardUI();
    } else if (ch.guesses.length >= ch.maxGuesses) {
      ch.revealed = true;
    }

    persistCurrentRankedState("chemle");
    $("chemle-search-input").value = "";
    closeChemleDropdown();
    renderChemleView();
  }

  // ---------------------------------------------------------------------------
  // 6. Accessible Chemle Autocomplete Combobox (`P0-3`, `P2-2`)
  // ---------------------------------------------------------------------------
  function closeChemleDropdown() {
    const dd = $("chemle-dropdown");
    const input = $("chemle-search-input");
    if (dd) dd.classList.remove("open");
    if (input) {
      input.setAttribute("aria-expanded", "false");
      input.removeAttribute("aria-activedescendant");
    }
  }

  function updateChemleDropdown(query) {
    const ch = activeChemle();
    const dd = $("chemle-dropdown");
    const input = $("chemle-search-input");
    if (ch.revealed || ch.won) {
      closeChemleDropdown();
      return;
    }

    // P0-3: Search ALWAYS queries the full 36-compound guessPool!
    const q = (query || "").trim().toLowerCase();
    const fullGuessPool = getGuessPool(DATA, "chemle");
    const matches = fullGuessPool.filter((m) => {
      if (ch.guesses.includes(m.id)) return false;
      if (!q) return true;
      return (
        m.name.toLowerCase().includes(q) ||
        m.Category.toLowerCase().includes(q) ||
        m.Formula.toLowerCase().includes(q) ||
        m.functional_groups.some((fg) => fg.toLowerCase().includes(q))
      );
    });

    // In Learn mode with a pack selected, sort pack members first while keeping all 36 selectable
    if (state.profile === "learn" && state.learnCategoryFilter !== "ALL") {
      matches.sort((a, b) => {
        const aIn = a.Category === state.learnCategoryFilter ? 0 : 1;
        const bIn = b.Category === state.learnCategoryFilter ? 0 : 1;
        if (aIn !== bIn) return aIn - bIn;
        return a.name.localeCompare(b.name);
      });
    }

    ch.filteredOptions = matches;
    ch.activeDropdownIdx = matches.length > 0 ? 0 : -1;

    if (matches.length === 0) {
      dd.innerHTML = `<div class="chemle-opt" role="option" aria-disabled="true" style="color:var(--muted-foreground);">No remaining molecules match "${escapeHtml(query)}"</div>`;
      dd.classList.add("open");
      input.setAttribute("aria-expanded", "true");
      return;
    }

    dd.innerHTML = matches
      .map((m, idx) => {
        const optId = `chemle-opt-${m.id}`;
        const inPack =
          state.profile === "learn" &&
          state.learnCategoryFilter !== "ALL" &&
          m.Category === state.learnCategoryFilter;
        // P0-1: Do NOT show exact MW or IG bits in pre-guess search dropdown!
        return `
      <div id="${optId}"
           class="chemle-opt ${idx === ch.activeDropdownIdx ? "active" : ""}"
           role="option"
           aria-selected="${idx === ch.activeDropdownIdx ? "true" : "false"}"
           data-mol-id="${m.id}">
        <div>
          <strong>${escapeHtml(m.name)}</strong>
          <span style="font-size:11px;color:var(--muted-foreground);margin-left:6px;">${formatFormula(m.Formula)}</span>
        </div>
        <div style="display:flex;gap:5px;align-items:center;">
          ${inPack ? `<span class="badge badge-emerald">In Active Pack</span>` : ""}
          <span class="badge badge-indigo">${escapeHtml(m.Category)}</span>
        </div>
      </div>
    `;
      })
      .join("");
    dd.classList.add("open");
    input.setAttribute("aria-expanded", "true");
    if (ch.activeDropdownIdx >= 0 && matches[ch.activeDropdownIdx]) {
      input.setAttribute(
        "aria-activedescendant",
        `chemle-opt-${matches[ch.activeDropdownIdx].id}`
      );
    }

    dd.querySelectorAll(".chemle-opt[data-mol-id]").forEach((el) => {
      el.addEventListener("click", () => {
        submitChemleGuess(el.getAttribute("data-mol-id"));
      });
    });
  }

  function highlightDropdownOption(newIdx) {
    const ch = activeChemle();
    const dd = $("chemle-dropdown");
    const input = $("chemle-search-input");
    const opts = dd.querySelectorAll(".chemle-opt[data-mol-id]");
    if (!opts.length) return;
    ch.activeDropdownIdx = ((newIdx % opts.length) + opts.length) % opts.length;
    opts.forEach((el, idx) => {
      const active = idx === ch.activeDropdownIdx;
      el.classList.toggle("active", active);
      el.setAttribute("aria-selected", active ? "true" : "false");
      if (active) {
        input.setAttribute("aria-activedescendant", el.id);
        if (typeof el.scrollIntoView === "function") {
          el.scrollIntoView({ block: "nearest" });
        }
      }
    });
  }

  // ---------------------------------------------------------------------------
  // 7. SEQLE Rendering & Gameplay (`P0-1`, `P0-4`, `P1-1`)
  // ---------------------------------------------------------------------------
  function renderSeqleView() {
    const sq = activeSeqle();
    const t = sq.target;
    const profSpec = activeProfileSpec();
    const ansPool = getAnswerPool(DATA, "seqle", state.profile, state.learnCategoryFilter);
    const maxLvl = getUnlockedClueLevel(sq, state.profile);
    const ladder = (t.clue_ladder && t.clue_ladder[state.profile]) || [];
    const clueConstraint = {
      profileId: state.profile,
      level0Text: ladder[0] ? ladder[0].text : null,
      level1Text: maxLvl >= 1 && ladder[1] ? ladder[1].text : null,
    };

    syncHintButtonUI();
    $("seqle-try-counter").textContent = `Guesses: ${sq.guesses.length} / ${sq.maxGuesses}`;
    const compat = countCompatibleSeqleCandidates(
      sq.guesses,
      t,
      ansPool,
      DATA.aa_properties,
      profSpec,
      clueConstraint
    );
    const candPill = $("seqle-candidates-pill");
    if (candPill) {
      candPill.textContent = `Candidates: ${compat} / ${ansPool.length}`;
    }

    const banner = $("seqle-banner");
    if (sq.won) {
      banner.className = "toast-banner show win";
      banner.innerHTML = `
        <div>🎉 <strong>Motif Decoded in ${sq.guesses.length}/${sq.maxGuesses}!</strong> <strong>${sq.target.seq}</strong> — ${escapeHtml(sq.target.title)}.</div>
        <div style="display:flex;gap:6px;">
          <button class="btn" onclick="window.__bwCopyShare()">📋 Share</button>
          ${state.profile === "learn" ? `<button class="btn btn-primary" onclick="window.__bwNewPuzzle()">Next Motif →</button>` : ""}
        </div>
      `;
    } else if (sq.revealed) {
      banner.className = "toast-banner show lose";
      banner.innerHTML = `
        <div>🧬 <strong>Target Motif Revealed:</strong> <strong>${sq.target.seq}</strong> (${escapeHtml(sq.target.title)}).</div>
        <div style="display:flex;gap:6px;">
          <button class="btn" onclick="window.__bwCopyShare()">📋 Share</button>
          ${state.profile === "learn" ? `<button class="btn btn-primary" onclick="window.__bwNewPuzzle()">Try Another →</button>` : ""}
        </div>
      `;
    } else {
      banner.className = "toast-banner";
      banner.innerHTML = "";
    }

    renderSeqleBoard();
    renderSeqleKeyboard();
    renderSeqleInspector();
  }

  function renderSeqleBoard() {
    const sq = activeSeqle();
    const t = sq.target;
    const profSpec = activeProfileSpec();
    const board = $("seqle-board");
    const rowsHtml = [];

    const stateGlyph = {
      exact: "✓",
      present: "⇄",
      class: "≈",
      absent: "·",
    };

    for (let r = 0; r < sq.maxGuesses; r++) {
      if (r < sq.guesses.length) {
        const g = sq.guesses[r];
        const fb = evaluateSeqleFeedbackFromSpec(
          g.seq,
          t.seq,
          DATA.aa_properties,
          profSpec,
          g.biochem,
          t
        );
        const tilesHtml = g.seq
          .split("")
          .map((aa, idx) => {
            const p = DATA.aa_properties[aa];
            const st = fb.tiles[idx];
            return `
            <div class="seqle-tile state-${st}" role="gridcell" title="Pos ${idx + 1}: ${p.name} (${p.three}) — Primary Class: ${p.group}">
              <span>${aa}</span>
              <span class="tile-sub">${p.three} ${stateGlyph[st]}</span>
            </div>
          `;
          })
          .join("");

        const stripCellsHtml = fb.strip
          .map(
            (sc) => `
              <div class="strip-metric" title="${escapeHtml(sc.label)}">
                <span class="prop-label">${escapeHtml(sc.label)}</span>
                <span class="prop-val">${sc.name === "net_charge_ph74" && sc.value > 0 ? "+" : ""}${sc.value} ${sc.arrow}</span>
              </div>
            `
          )
          .join("");

        rowsHtml.push(`
          <div class="seqle-row" role="row">
            ${tilesHtml}
            <div class="seqle-biochem-strip">
              ${stripCellsHtml}
            </div>
          </div>
        `);
      } else if (r === sq.guesses.length && !sq.revealed && !sq.won) {
        const chars = sq.currentInput.split("");
        const tilesHtml = [0, 1, 2, 3, 4]
          .map((idx) => {
            const aa = chars[idx] || "";
            const p = aa ? DATA.aa_properties[aa] : null;
            return `
            <div class="seqle-tile ${aa ? "filled" : ""}" role="gridcell">
              <span>${aa}</span>
              <span class="tile-sub">${p ? p.three : ""}</span>
            </div>
          `;
          })
          .join("");

        const liveBio =
          sq.currentInput.length === 5
            ? computePeptideBiochem(sq.currentInput, DATA.aa_properties)
            : null;
        const stripHtml = liveBio
          ? `
            <div class="strip-metric"><span class="prop-label">pH 7.4 Q</span><span class="prop-val">${liveBio.net_charge_ph74 > 0 ? "+" : ""}${liveBio.net_charge_ph74}</span></div>
            <div class="strip-metric"><span class="prop-label">GRAVY</span><span class="prop-val">${liveBio.gravy}</span></div>
            <div class="strip-metric"><span class="prop-label">pI</span><span class="prop-val">${liveBio.isoelectric_point}</span></div>
          `
          : `<div style="grid-column:1/-1;font-size:11px;color:var(--muted-foreground);">Type 5 standard amino acids (A–Y) or pick a curated motif above</div>`;

        rowsHtml.push(`
          <div class="seqle-row" role="row">
            ${tilesHtml}
            <div class="seqle-biochem-strip">${stripHtml}</div>
          </div>
        `);
      } else {
        const emptyTiles = [0, 1, 2, 3, 4]
          .map(() => `<div class="seqle-tile" role="gridcell"></div>`)
          .join("");
        rowsHtml.push(`
          <div class="seqle-row" role="row" style="opacity:0.45;">
            ${emptyTiles}
            <div class="seqle-biochem-strip"></div>
          </div>
        `);
      }
    }

    board.innerHTML = rowsHtml.join("");
  }

  function renderSeqleKeyboard() {
    const sq = activeSeqle();
    const kb = $("seqle-keyboard");
    const groups = [
      { title: "Aliphatic (Nonpolar)", codes: ["A", "V", "I", "L", "M"] },
      { title: "Aromatic", codes: ["F", "Y", "W"] },
      { title: "Polar Uncharged", codes: ["S", "T", "N", "Q"] },
      { title: "Positively Charged", codes: ["K", "R", "H"] },
      { title: "Negatively Charged", codes: ["D", "E"] },
      { title: "Special (Thiol / Turn)", codes: ["C", "G", "P"] },
    ];

    kb.innerHTML = groups
      .map((g) => {
        const keysHtml = g.codes
          .map((aa) => {
            const p = DATA.aa_properties[aa];
            const st = sq.keyStates[aa] ? `key-${sq.keyStates[aa]}` : "";
            return `
            <button type="button" class="aa-key ${st}" data-aa="${aa}" title="${p.name} (${p.three}) · Traits: ${(p.traits || []).join(", ")} · KD: ${p.hydropathy}">
              <span>${aa}</span>
              <small>${p.three}</small>
            </button>
          `;
          })
          .join("");
        return `
        <div class="aa-group-box">
          <div class="aa-group-title"><span>${g.title}</span></div>
          <div class="aa-keys-row">${keysHtml}</div>
        </div>
      `;
      })
      .join("");

    kb.querySelectorAll(".aa-key").forEach((btn) => {
      btn.addEventListener("click", () => {
        handleSeqleKeyInput(btn.getAttribute("data-aa"));
      });
    });
  }

  function renderSeqleInspector() {
    const sq = activeSeqle();
    const t = sq.target;
    const well = $("seqle-structure-well");
    const stageBadge = $("seqle-clue-stage");
    const hintsList = $("seqle-hints-list");
    const fullProps = $("seqle-full-props");

    const maxLvl = getUnlockedClueLevel(sq, state.profile);
    const ladder = (t.clue_ladder && t.clue_ladder[state.profile]) || [];

    if (sq.revealed) {
      well.className = "chem-svg-well";
      well.innerHTML =
        t.svg_full +
        `<span class="well-overlay-tag">${t.seq} (${escapeHtml(t.three_letter)})</span>`;
      stageBadge.textContent = "Revealed";
      stageBadge.className = "badge badge-emerald";
    } else {
      well.className = "chem-svg-well silhouette";
      well.innerHTML =
        t.svg_full +
        `<span class="well-overlay-tag">Pentapeptide 2D Backbone (Hidden)</span>`;
      stageBadge.textContent = `Level ${maxLvl} · ${maxLvl === 0 ? "k-Anonymous" : "Clues Active"}`;
      stageBadge.className = "badge badge-indigo";
    }

    const visibleClues = ladder.filter((c) => c.level <= maxLvl);
    let html = visibleClues
      .map(
        (c) => `
        <div class="hint-item">
          <strong>${escapeHtml(c.title)}</strong>
          ${escapeHtml(c.text)}
        </div>`
      )
      .join("");

    if (!sq.revealed && maxLvl < 3) {
      const nextClue = ladder.find((c) => c.level === maxLvl + 1);
      if (nextClue) {
        const unlockMsg =
          state.profile === "ranked"
            ? `Auto-unlocks after Guess ${nextClue.after_guesses}`
            : `Click 💡 Hint to unlock ${nextClue.title}`;
        html += `
          <div class="hint-item" style="opacity:0.75;border-style:dashed;">
            <strong>Locked · ${escapeHtml(nextClue.title)}</strong>
            ${escapeHtml(unlockMsg)}
          </div>`;
      }
    }

    hintsList.innerHTML = html;

    if (sq.revealed) {
      fullProps.style.display = "block";
      const kindBadge =
        t.kind === "exact"
          ? `<span class="badge badge-emerald">Exact 5-Mer Motif</span>`
          : t.kind === "fragment"
          ? `<span class="badge badge-cyan">5-Mer Window of Longer Motif</span>`
          : `<span class="badge badge-amber">Pedagogical Abstraction (Learn-Only)</span>`;

      const termLabel =
        t.terminal === "C"
          ? "Extreme C-terminus (-COOH required)"
          : t.terminal === "N"
          ? "Extreme N-terminus (free α-NH3+ required)"
          : "Internal / Non-terminal";

      fullProps.innerHTML = `
        <div class="hint-item" style="margin-top:8px;">
          <strong>Motif Representation &amp; Structural Context (P0-4)</strong>
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin:4px 0;">
            ${kindBadge}
            <span class="badge badge-indigo">Consensus: ${escapeHtml(t.consensus)}</span>
          </div>
          <div>${escapeHtml(t.context_requirement)}</div>
          <div style="margin-top:4px;font-size:11px;color:var(--muted-foreground);">
            <b>Parent Sequence Window:</b> <code>${escapeHtml(t.parent_sequence)}</code> (offset ${t.window_offset}, ${termLabel})<br/>
            <b>Exemplar Reference:</b> ${escapeHtml(t.exemplar_source)}
          </div>
        </div>
        <div class="prop-grid">
          <div class="prop-cell"><span class="prop-label">Sequence</span><span class="prop-val">${t.seq} (${t.three_letter})</span></div>
          <div class="prop-cell"><span class="prop-label">Family</span><span class="prop-val">${escapeHtml(t.family)}</span></div>
          <div class="prop-cell"><span class="prop-label">Formula</span><span class="prop-val">${formatFormula(t.Formula)}</span></div>
          <div class="prop-cell"><span class="prop-label">MW</span><span class="prop-val">${t.MW} Da</span></div>
          <div class="prop-cell"><span class="prop-label">pH 7.4 Charge</span><span class="prop-val">${t.net_charge_ph74 > 0 ? "+" : ""}${t.net_charge_ph74}</span></div>
          <div class="prop-cell"><span class="prop-label">GRAVY</span><span class="prop-val">${t.gravy}</span></div>
          <div class="prop-cell"><span class="prop-label">pI</span><span class="prop-val">${t.isoelectric_point}</span></div>
          <div class="prop-cell"><span class="prop-label">Opening IG</span><span class="prop-val">${t.information_gain_bits} bits</span></div>
        </div>
      `;
    } else {
      fullProps.style.display = "none";
      fullProps.innerHTML = "";
    }
  }

  function handleSeqleKeyInput(char) {
    const sq = activeSeqle();
    if (sq.revealed || sq.won) return;
    const up = (char || "").toUpperCase();
    if (DATA.aa_properties[up] && sq.currentInput.length < 5) {
      sq.currentInput += up;
      renderSeqleBoard();
    }
  }

  function handleSeqleBackspace() {
    const sq = activeSeqle();
    if (sq.revealed || sq.won) return;
    if (sq.currentInput.length > 0) {
      sq.currentInput = sq.currentInput.slice(0, -1);
      renderSeqleBoard();
    }
  }

  function submitSeqleGuess() {
    if (state.profile === "ranked" && checkAndHandleUtcRollover()) return;
    const sq = activeSeqle();
    if (sq.revealed || sq.won) return;
    if (sq.currentInput.length !== 5) return;

    const guessSeq = sq.currentInput;
    const profSpec = activeProfileSpec();
    const knownMotif = SEQ_BY_CODE[guessSeq] || null;
    const biochem = knownMotif
      ? {
          gravy: knownMotif.gravy,
          net_charge_ph74: knownMotif.net_charge_ph74,
          isoelectric_point: knownMotif.isoelectric_point,
          aromatic_count: knownMotif.aromatic_count,
          polar_count: knownMotif.polar_count,
          residue_groups: knownMotif.residue_groups,
        }
      : computePeptideBiochem(guessSeq, DATA.aa_properties);

    const fb = evaluateSeqleFeedbackFromSpec(
      guessSeq,
      sq.target.seq,
      DATA.aa_properties,
      profSpec,
      biochem,
      sq.target
    );

    const prio = { exact: 4, present: 3, class: 2, absent: 1 };
    for (let i = 0; i < 5; i++) {
      const aa = guessSeq[i];
      const st = fb.tiles[i];
      const cur = sq.keyStates[aa];
      if (!cur || prio[st] > prio[cur]) {
        sq.keyStates[aa] = st;
      }
    }

    sq.guesses.push({
      seq: guessSeq,
      states: fb.tiles,
      biochem,
      knownMotif,
    });
    sq.currentInput = "";

    if (guessSeq === sq.target.seq) {
      sq.won = true;
      sq.revealed = true;
      if (state.profile === "ranked" && !state.customSeed) {
        state.stats = evaluateDailyWinStreak(state.stats, "seqle", sq.utcDate || getUtcDateString());
      } else {
        state.stats.seqWins = (state.stats.seqWins || 0) + 1;
      }
      saveStatsV2(state.stats);
      updateScoreboardUI();
    } else if (sq.guesses.length >= sq.maxGuesses) {
      sq.revealed = true;
    }

    persistCurrentRankedState("seqle");
    renderSeqleView();
  }

  // ---------------------------------------------------------------------------
  // 8. Color-Independent Emoji & Glyph Share Card (`P3-2`)
  // ---------------------------------------------------------------------------
  function buildShareCard() {
    const utcDate = getUtcDateString();
    const profTag = state.customSeed
      ? `Seed:${state.customSeed}`
      : state.profile === "ranked"
      ? `Ranked UTC ${utcDate}`
      : `Learn Mode`;

    if (state.mode === "chemle") {
      const ch = activeChemle();
      const t = ch.target;
      const profSpec = activeProfileSpec();
      const score = ch.won ? `${ch.guesses.length}/${ch.maxGuesses}` : `X/${ch.maxGuesses}`;
      const rows = ch.guesses.map((gId, idx) => {
        const g = CHEM_BY_ID[gId];
        const sim = DATA.chemle_similarity[gId][t.id];
        const fb = evaluateChemleFeedbackFromSpec(g, t, sim, profSpec);
        const cells = fb.cells.map((c) => {
          const blk = c.cls === "match-exact" ? "🟩" : c.cls === "match-close" ? "🟨" : "⬜";
          return `${blk}${c.arrow}`;
        });
        return `#${idx + 1} ${cells.join(" ")} | Sim:${fb.sim_code}`;
      });
      return [
        `BioWordle v0.2 · Chemle (${profTag}) ${score} [db:${DATASET_HASH.slice(0, 6)}]`,
        ...rows,
      ].join("\n");
    } else {
      const sq = activeSeqle();
      const t = sq.target;
      const profSpec = activeProfileSpec();
      const score = sq.won ? `${sq.guesses.length}/${sq.maxGuesses}` : `X/${sq.maxGuesses}`;
      const tileEmoji = {
        exact: "🟩✓",
        present: "🟨⇄",
        class: "🟦≈",
        absent: "⬛·",
      };
      const rows = sq.guesses.map((g, idx) => {
        const fb = evaluateSeqleFeedbackFromSpec(
          g.seq,
          t.seq,
          DATA.aa_properties,
          profSpec,
          g.biochem,
          t
        );
        return `#${idx + 1} ${fb.tiles.map((s) => tileEmoji[s]).join(" ")}`;
      });
      return [
        `BioWordle v0.2 · Seqle (${profTag}) ${score} [db:${DATASET_HASH.slice(0, 6)}]`,
        ...rows,
      ].join("\n");
    }
  }

  function copyShareCardToClipboard() {
    const text = buildShareCard();
    if (globalScope.navigator && globalScope.navigator.clipboard) {
      globalScope.navigator.clipboard.writeText(text).catch(() => {});
    }
    const banner = $(state.mode === "chemle" ? "chemle-banner" : "seqle-banner");
    if (banner) {
      banner.className = "toast-banner show win";
      banner.innerHTML = `<div>📋 <strong>Copied Share Card:</strong> <code style="font-size:11px;">${escapeHtml(text.replace(/\n/g, " · "))}</code></div>`;
    }
  }

  // ---------------------------------------------------------------------------
  // 9. Mode Switching & Event Bindings
  // ---------------------------------------------------------------------------
  function switchGameMode(newMode) {
    state.mode = newMode;
    const isChem = newMode === "chemle";
    $("tab-chemle").classList.toggle("active", isChem);
    $("tab-chemle").setAttribute("aria-selected", isChem ? "true" : "false");
    $("tab-seqle").classList.toggle("active", !isChem);
    $("tab-seqle").setAttribute("aria-selected", !isChem ? "true" : "false");
    $("view-chemle").style.display = isChem ? "grid" : "none";
    $("view-seqle").style.display = isChem ? "none" : "grid";

    checkAndHandleUtcRollover();
    ensureSessionInitialized(newMode, state.profile, false);
    if (isChem) renderChemleView();
    else renderSeqleView();
  }

  function switchProfile(newProfile) {
    state.profile = newProfile;
    checkAndHandleUtcRollover();
    syncHeaderAndProfileControls();
    ensureSessionInitialized("chemle", state.profile, false);
    ensureSessionInitialized("seqle", state.profile, false);
    if (state.mode === "chemle") renderChemleView();
    else renderSeqleView();
  }

  function boot() {
    updateScoreboardUI();
    updateUtcCountdownUI();
    setInterval(updateUtcCountdownUI, 1000);

    if (DATA.metadata && $("app-meta-subtitle")) {
      $("app-meta-subtitle").textContent = `RDKit ${DATA.metadata.rdkit_version} · v${DATA.metadata.schema_version} · DB #${DATA.metadata.dataset_version_hash.slice(0, 8)} · ${DATA.metadata.chemle_count} Mols · ${DATA.metadata.seqle_ranked_count} Ranked / ${DATA.metadata.seqle_count} Learn Motifs`;
    }

    syncHeaderAndProfileControls();
    ensureSessionInitialized("chemle", "ranked", false);
    ensureSessionInitialized("seqle", "ranked", false);
    ensureSessionInitialized("chemle", "learn", false);
    ensureSessionInitialized("seqle", "learn", false);

    renderChemleView();
    renderSeqleView();

    $("tab-chemle").addEventListener("click", () => switchGameMode("chemle"));
    $("tab-seqle").addEventListener("click", () => switchGameMode("seqle"));

    $("btn-playstyle").addEventListener("click", () => {
      const nextProf = state.profile === "ranked" ? "learn" : "ranked";
      switchProfile(nextProf);
    });

    $("btn-new-puzzle").addEventListener("click", () => {
      if (state.profile === "ranked" && !state.customSeed) {
        switchProfile("learn");
      }
      ensureSessionInitialized(state.mode, state.profile, true);
      if (state.mode === "chemle") renderChemleView();
      else renderSeqleView();
    });

    $("btn-hint").addEventListener("click", () => {
      if (state.profile === "ranked") {
        checkAndHandleUtcRollover();
        return;
      }
      if (state.mode === "chemle") {
        const ch = activeChemle();
        const curLvl = getUnlockedClueLevel(ch, "learn");
        if (!ch.revealed && curLvl < 3) {
          ch.hintLevelUnlocked = curLvl + 1;
          renderChemleView();
        }
      } else {
        const sq = activeSeqle();
        const curLvl = getUnlockedClueLevel(sq, "learn");
        if (!sq.revealed && curLvl < 3) {
          sq.hintLevelUnlocked = curLvl + 1;
          renderSeqleView();
        }
      }
    });

    $("btn-share").addEventListener("click", () => {
      copyShareCardToClipboard();
    });

    $("btn-giveup").addEventListener("click", () => {
      if (state.profile === "ranked" && checkAndHandleUtcRollover()) return;
      if (state.mode === "chemle") {
        const ch = activeChemle();
        ch.revealed = true;
        persistCurrentRankedState("chemle");
        renderChemleView();
      } else {
        const sq = activeSeqle();
        sq.revealed = true;
        persistCurrentRankedState("seqle");
        renderSeqleView();
      }
    });

    $("btn-theme").addEventListener("click", () => {
      document.documentElement.classList.toggle("dark");
    });

    $("chemle-cat-filter").addEventListener("change", (e) => {
      if (state.profile !== "learn") return;
      state.learnCategoryFilter = e.target.value;
      ensureSessionInitialized("chemle", "learn", true);
      renderChemleView();
    });

    const searchInput = $("chemle-search-input");
    searchInput.addEventListener("focus", (e) => updateChemleDropdown(e.target.value));
    searchInput.addEventListener("input", (e) => updateChemleDropdown(e.target.value));
    searchInput.addEventListener("keydown", (e) => {
      const ch = activeChemle();
      const dd = $("chemle-dropdown");
      if (!dd.classList.contains("open")) {
        if (e.key === "ArrowDown") {
          updateChemleDropdown(searchInput.value);
          e.preventDefault();
        }
        return;
      }
      if (e.key === "ArrowDown") {
        highlightDropdownOption(ch.activeDropdownIdx + 1);
        e.preventDefault();
      } else if (e.key === "ArrowUp") {
        highlightDropdownOption(ch.activeDropdownIdx - 1);
        e.preventDefault();
      } else if (e.key === "Enter") {
        if (
          ch.filteredOptions &&
          ch.filteredOptions.length > 0 &&
          ch.activeDropdownIdx >= 0
        ) {
          submitChemleGuess(ch.filteredOptions[ch.activeDropdownIdx].id);
          e.preventDefault();
        }
      } else if (e.key === "Escape") {
        closeChemleDropdown();
      }
    });

    document.addEventListener("click", (e) => {
      if (!e.target.closest(".chemle-search-bar")) {
        closeChemleDropdown();
      }
    });

    $("seqle-motif-picker").addEventListener("change", (e) => {
      const val = e.target.value;
      const sq = activeSeqle();
      if (val && !sq.revealed && !sq.won) {
        sq.currentInput = val;
        renderSeqleBoard();
      }
      e.target.value = "";
    });

    $("seqle-btn-backspace").addEventListener("click", handleSeqleBackspace);
    $("seqle-btn-submit").addEventListener("click", submitSeqleGuess);

    document.addEventListener("keydown", (e) => {
      if (state.mode !== "seqle") return;
      if (["INPUT", "SELECT", "TEXTAREA"].includes(document.activeElement.tagName)) return;
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      if (e.key === "Backspace") {
        handleSeqleBackspace();
        e.preventDefault();
      } else if (e.key === "Enter") {
        submitSeqleGuess();
        e.preventDefault();
      } else if (/^[a-zA-Z]$/.test(e.key)) {
        handleSeqleKeyInput(e.key);
      }
    });

    globalScope.__bwNewPuzzle = () => $("btn-new-puzzle").click();
    globalScope.__bwCopyShare = () => copyShareCardToClipboard();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})(typeof window !== "undefined" ? window : globalThis);
